-- NEBULA 2.0 | Migracion 002: cargar pensum UNAB de 9 semestres.
-- Derivada de los CSV originales del proyecto previo, validados antes de generar.
-- Requiere 001 y ejecutarse como postgres en el proyecto nebula-academica-v2.
-- Idempotente por huella SHA-256: mismo lote = sin cambios; lote distinto = error.
-- NO contiene datos de estudiantes ni inventa prerrequisitos.
-- ATENCION: ejecutar el archivo completo de BEGIN a COMMIT.

BEGIN ISOLATION LEVEL READ COMMITTED;
SET LOCAL search_path = pg_catalog, academic;
DO $lock$ BEGIN PERFORM pg_advisory_xact_lock(6033, 1); END; $lock$;
DO $import$
DECLARE
    existing_digest text;
    new_evidence_id bigint;
    resolved_course_id bigint;
BEGIN
-- Supabase PostgreSQL: validar esquema y migracion, sin exigir nombre de base de datos.
IF NOT EXISTS (SELECT FROM academic.schema_migrations WHERE version = 1) THEN
    RAISE EXCEPTION 'Academic migration 001 is required';
END IF;
SELECT sha256 INTO existing_digest
FROM academic.import_batches WHERE curriculum_id = convert_from(decode('4e4542554c412d554e41422d49532d39532d5631', 'hex'), 'UTF8');
IF existing_digest IS NOT NULL THEN
    IF existing_digest <> convert_from(decode('65353262643363323036643463643664326239663266653034323965353435366538313730366439323965656663363866636439633239353562346535323332', 'hex'), 'UTF8') THEN
        RAISE EXCEPTION 'CSV fingerprint differs for this curriculum revision';
    END IF;
    PERFORM set_config('nebula.import_result', 'already_imported', true);
    RETURN;
END IF;
PERFORM set_config('nebula.import_result', 'imported', true);
END;
$import$;
SELECT current_setting('nebula.import_result');
COMMIT;
